Schema:
CREATE TABLE customers (
    id INTEGER PRIMARY KEY,
    name TEXT NOT NULL,
    country_code TEXT NOT NULL
);

CREATE TABLE orders (
    id INTEGER PRIMARY KEY,
    customer_id INTEGER NOT NULL,
    amount REAL NOT NULL,
    order_date TEXT NOT NULL,
    FOREIGN KEY(customer_id) REFERENCES customers(id)
);

CREATE TABLE campaigns (
    id INTEGER PRIMARY KEY,
    name TEXT NOT NULL
);

CREATE TABLE order_promotions (
    order_id INTEGER NOT NULL,
    campaign_id INTEGER NOT NULL,
    source_event TEXT NOT NULL,
    FOREIGN KEY(order_id) REFERENCES orders(id),
    FOREIGN KEY(campaign_id) REFERENCES campaigns(id)
);

Semantic model:
{
  "dimensions": {
    "campaign_name": {
      "column": "name",
      "table": "campaigns"
    },
    "customer_country": {
      "aliases": {
        "France": "FR",
        "United States": "US"
      },
      "column": "country_code",
      "table": "customers"
    },
    "customer_name": {
      "column": "name",
      "table": "customers"
    }
  },
  "entities": {
    "campaign": {
      "display": "name",
      "primary_key": "id",
      "table": "campaigns"
    },
    "customer": {
      "display": "name",
      "primary_key": "id",
      "table": "customers"
    }
  },
  "fanout_rules": {
    "order_promotions": "dedupe_bridge_rows before summing order revenue"
  },
  "joins": [
    "orders.customer_id = customers.id",
    "order_promotions.order_id = orders.id",
    "order_promotions.campaign_id = campaigns.id"
  ],
  "measures": {
    "revenue": {
      "expression": "SUM(orders.amount)",
      "grain": "one row per order"
    }
  },
  "semantic_model_id": "synthetic_revenue_v1",
  "version": "1"
}

Value index:
{
  "artifact_type": "synthetic_non_oracle_value_index",
  "entries": [
    {
      "column": "country_code",
      "display_value": "France",
      "storage_value": "FR",
      "table": "customers"
    },
    {
      "column": "country_code",
      "display_value": "United States",
      "storage_value": "US",
      "table": "customers"
    }
